 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    if (scwin.getProvider() === 'POPUPMODE') {
        // 회사코드 셋팅
        txb_isur_cd.setValue(scwin.gIsurCd);
        txb_com_abbrv.setValue(scwin.gCOM_NM);
