/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let SDate = edt_SDate.getValue();
    const basicVal = $c.ut.isDate(SDate);
    if (basicVal === false) {
        await $c.win.alert("[조회기준일]의 날짜형식이 정확하지 않습니다.");
        return false;
    }
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&EDU_KIND_CD=" + cmb_EDU_KIND_CD.getValue();
    url += "&BASE_DT=" + SDate;
    url += "&EMP_NO=" + cmb_EMP_NO.getValue();
    url += "&DEP_CD=" + cmb_DEP_CD.getValue();
    url += "&DUTY_EDU_YN=" + cmb_DUTY_EDU_YN.getValue();
    url += "&YEAR_EDU_PASS_YN=" + cmb_YEAR_EDU_PASS_YN.getValue();
    url += "&LNGTRM_CONTSVC_YN=" + cmb_LNGTRM_CONTSVC_YN.getValue();
    url += "&EXCNT_DISCLS_CORP=" + cmb_EXCNT_DISCLS_CORP.getValue();
    url += "&SCREN_ID=" + "ULDSTF30619.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

