/**
 * @method
 * @name check
 * @description check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check = async function() {
    let checkCnt = 0;
    for (let i = 1; i <= dts_MASTER.getRowCount(); i++) {
        if (dts_MASTER.getCellData(i, "CHECK") === "T") {
            checkCnt++;
        }
    }
    if (checkCnt <= 0) {
        await $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description 2017.12.21
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 선택한 항목이 있는지 check
    if (await scwin.check() === true) {
        await scwin.setHeader();
        let gCnt = 0;
        dts_UpdateList.setBroadcast(false);
        for (let i = 1, k = 1; i <= dts_MASTER.getRowCount(); i++) {
            if (dts_MASTER.getCellData(i, "CHECK") === "T") {
                dts_UpdateList.insertRow();
                dts_UpdateList.setCellData(k, "ISUR_CD", dts_MASTER.getCellData(i, "ISUR_CD"));
                dts_UpdateList.setCellData(k, "CHRG_DESIGN_DD", dts_MASTER.getCellData(i, "CHRG_DESIGN_DD"));
                dts_UpdateList.setCellData(k, "CHRG_NM", dts_MASTER.getCellData(i, "CHRG_NM"));
                dts_UpdateList.setCellData(k, "CHRG_TP_CD", dts_MASTER.getCellData(i, "CHRG_TP_CD"));
                dts_UpdateList.setCellData(k, "NEW_EDU_COMPLT_YN", dts_MASTER.getCellData(i, "NEW_EDU_COMPLT_YN"));
                dts_UpdateList.setCellData(k, "REMK", "");
                dts_UpdateList.setCellData(k, "TRANSTR_EMP_NO", scwin.gEmpNo);
                k++;
                gCnt++;
            }
        }
        dts_UpdateList.setBroadcast(true, true);
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + gCnt + '건을 저장'))) return;
        scwin.procJob = "신규교육이수여부 저장";
        trs_save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/ListedCompany.do",
            ref : "dts_UpdateList",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

