/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gIsurCd = dts_MASTER.getCellData(Number(row), "ISUR_CD");
    scwin.gChrgNm = dts_MASTER.getCellData(Number(row), "CHRG_NM");
    scwin.gComAbbrv = dts_MASTER.getCellData(Number(row), "COM_ABBRV");
    scwin.gChrgTpNm = dts_MASTER.getCellData(Number(row), "CHRG_TP_NM");
    if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "LNGTRM_CONTSVC_YN") {
        const options = {
            id: "ULDSTF30632",
            title: "장기근속자 해당여부 관리",
            type: "browserPopup",
            width: "610px",
            height: "340px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/issueinfo/ULDSTF30632.gfm", options);
    } else if (colid === "YEAR_REAL_PASS_TIME") {
        $c.frame.path("/top").WinOpen("ULDSTF30618_REAL", "/issueinfo/ULDSTF30618.gfm?ISUR_CD=" + scwin.gIsurCd + "&COM_NM=" + scwin.gComAbbrv + "&" + frame.FrameID, "공시담당자등 교육참가현황(유)", 1300, 810);
    }
};

/**
